// netlify/functions/chat.js
//
// Funcion de Netlify (formato v2 / streaming) que conecta el chat de Growee
// con la API de Anthropic, enriqueciendo el system prompt con las
// metodologias relevantes para el mensaje del usuario.
//
// Las 200 metodologias van incrustadas directamente en este archivo (en vez
// de leerse de un metodologias.json aparte) para evitar problemas de rutas
// de archivo cuando Netlify empaqueta la funcion en distintos formatos.
//
// VARIABLES DE ENTORNO NECESARIAS (Netlify > Site configuration > Environment variables):
//   ANTHROPIC_API_KEY   -> tu clave de la API de Anthropic (console.anthropic.com)

const METODOLOGIAS = [{"id":"b001","modulo":"bienestar","nombre":"Terapia Cognitivo-Conductual (TCC)","autor":"Aaron Beck","anio":1960,"resumen":"Identifica y reestructura pensamientos automáticos distorsionados que generan malestar emocional, sustituyéndolos por interpretaciones más realistas.","cuando_usar":"Ansiedad, depresión leve-moderada, pensamientos rumiativos o catastrofistas."},{"id":"b002","modulo":"bienestar","nombre":"Terapia Racional Emotiva Conductual (TREC)","autor":"Albert Ellis","anio":1955,"resumen":"Modelo ABC: identifica la creencia irracional (B) entre el evento activador (A) y la consecuencia emocional (C) para disputarla.","cuando_usar":"Creencias rígidas o exigencias poco realistas ('debería', 'tengo que')."},{"id":"b003","modulo":"bienestar","nombre":"Terapia de Aceptación y Compromiso (ACT)","autor":"Steven Hayes","anio":1986,"resumen":"Fomenta aceptar pensamientos y emociones difíciles sin luchar contra ellos, actuando según los valores personales.","cuando_usar":"Evitación experiencial, bloqueo por miedo al malestar, pérdida de sentido."},{"id":"b004","modulo":"bienestar","nombre":"Terapia Dialéctico-Conductual (DBT)","autor":"Marsha Linehan","anio":1993,"resumen":"Combina aceptación y cambio; entrena regulación emocional, tolerancia al malestar y efectividad interpersonal.","cuando_usar":"Emociones intensas y desregulación, impulsividad, conflictos relacionales recurrentes."},{"id":"b005","modulo":"bienestar","nombre":"Reducción de Estrés Basada en Mindfulness (MBSR)","autor":"Jon Kabat-Zinn","anio":1979,"resumen":"Programa estructurado de atención plena para reducir la reactividad al estrés mediante la observación no reactiva del momento presente.","cuando_usar":"Estrés crónico, rumiación, dificultad para desconectar del trabajo."},{"id":"b006","modulo":"bienestar","nombre":"Terapia Cognitiva Basada en Mindfulness (MBCT)","autor":"Zindel Segal, Mark Williams, John Teasdale","anio":2002,"resumen":"Combina TCC y mindfulness para prevenir recaídas depresivas, interrumpiendo patrones de rumiación.","cuando_usar":"Historial de episodios depresivos, riesgo de recaída, rumiación negativa."},{"id":"b007","modulo":"bienestar","nombre":"Activación Conductual","autor":"Peter Lewinsohn / Christopher Martell","anio":2001,"resumen":"Aumenta gradualmente actividades placenteras o con sentido para romper el círculo de evitación y bajo ánimo.","cuando_usar":"Apatía, desmotivación, aislamiento, síntomas depresivos leves."},{"id":"b008","modulo":"bienestar","nombre":"Terapia Centrada en la Persona","autor":"Carl Rogers","anio":1951,"resumen":"Ofrece escucha empática, aceptación incondicional y autenticidad para que la persona encuentre su propia solución.","cuando_usar":"Necesidad de desahogo, procesos de autoexploración, baja autoestima."},{"id":"b009","modulo":"bienestar","nombre":"Terapia Focalizada en las Emociones (EFT)","autor":"Leslie Greenberg / Sue Johnson","anio":1985,"resumen":"Ayuda a identificar, procesar y transformar emociones primarias no expresadas que sostienen el malestar.","cuando_usar":"Emociones difusas o negadas, conflictos de pareja, dificultad para nombrar lo que se siente."},{"id":"b010","modulo":"bienestar","nombre":"Terapia Interpersonal (IPT)","autor":"Gerald Klerman, Myrna Weissman","anio":1984,"resumen":"Trabaja el malestar emocional a través de conflictos, duelos o transiciones en las relaciones interpersonales.","cuando_usar":"Conflictos con compañeros o jefes, duelo, cambios de rol."},{"id":"b011","modulo":"bienestar","nombre":"Terapia de Resolución de Problemas","autor":"Thomas D'Zurilla, Marvin Goldfried","anio":1971,"resumen":"Entrena un proceso estructurado (definir, generar opciones, decidir, actuar, evaluar) para afrontar problemas concretos.","cuando_usar":"Sensación de bloqueo ante una decisión o problema práctico concreto."},{"id":"b012","modulo":"bienestar","nombre":"Modelo Transteórico del Cambio","autor":"James Prochaska, Carlo DiClemente","anio":1983,"resumen":"Describe las etapas (precontemplación, contemplación, preparación, acción, mantenimiento) por las que pasa un cambio de hábito.","cuando_usar":"Resistencia a cambiar un hábito, ambivalencia sobre iniciar un cambio."},{"id":"b013","modulo":"bienestar","nombre":"Teoría de la Autodeterminación","autor":"Edward Deci, Richard Ryan","anio":1985,"resumen":"Explica la motivación intrínseca a través de tres necesidades: autonomía, competencia y relación.","cuando_usar":"Falta de motivación, sensación de trabajo impuesto o sin propósito."},{"id":"b014","modulo":"bienestar","nombre":"Psicología Positiva","autor":"Martin Seligman","anio":1998,"resumen":"Desplaza el foco del déficit a las fortalezas y emociones positivas como vía de bienestar sostenible.","cuando_usar":"Deseo de mejorar el bienestar general, no solo reducir el malestar."},{"id":"b015","modulo":"bienestar","nombre":"Modelo PERMA","autor":"Martin Seligman","anio":2011,"resumen":"Define cinco pilares del bienestar: emociones positivas, compromiso, relaciones, sentido y logro.","cuando_usar":"Diagnóstico general de qué área del bienestar está más descuidada."},{"id":"b016","modulo":"bienestar","nombre":"Terapia Narrativa","autor":"Michael White, David Epston","anio":1990,"resumen":"Ayuda a reescribir la historia personal separando a la persona del problema ('la persona no es el problema, el problema es el problema').","cuando_usar":"Identidad muy fusionada con una etiqueta o problema ('soy un fracaso')."},{"id":"b017","modulo":"bienestar","nombre":"Terapia Breve Centrada en Soluciones","autor":"Steve de Shazer, Insoo Kim Berg","anio":1982,"resumen":"Se centra en identificar excepciones al problema y construir sobre lo que ya funciona, en vez de analizar la causa.","cuando_usar":"Necesidad de avanzar rápido, foco en soluciones más que en el origen del malestar."},{"id":"b018","modulo":"bienestar","nombre":"Respiración Diafragmática","autor":"Basada en investigación en biofeedback y fisiología del estrés","anio":1970,"resumen":"Técnica de respiración lenta y profunda que activa el sistema nervioso parasimpático y reduce la activación fisiológica.","cuando_usar":"Ansiedad aguda, tensión física, previo a una situación estresante."},{"id":"b019","modulo":"bienestar","nombre":"Relajación Muscular Progresiva","autor":"Edmund Jacobson","anio":1938,"resumen":"Tensa y relaja grupos musculares de forma secuencial para reducir la tensión física asociada al estrés.","cuando_usar":"Tensión muscular, dificultad para conciliar el sueño, ansiedad somática."},{"id":"b020","modulo":"bienestar","nombre":"Entrenamiento Autógeno","autor":"Johannes Schultz","anio":1932,"resumen":"Autosugestión guiada de sensaciones de peso y calor corporal para inducir un estado de relajación profunda.","cuando_usar":"Estrés crónico, dificultad para relajarse conscientemente."},{"id":"b021","modulo":"bienestar","nombre":"Técnica de Grounding 5-4-3-2-1","autor":"Basada en terapia sensorial del trauma","anio":1990,"resumen":"Usa los cinco sentidos para anclar la atención al presente y reducir la disociación o la ansiedad aguda.","cuando_usar":"Ataques de pánico, sensación de desconexión, ansiedad muy intensa."},{"id":"b022","modulo":"bienestar","nombre":"EMDR (Desensibilización y Reprocesamiento por Movimientos Oculares)","autor":"Francine Shapiro","anio":1987,"resumen":"Procesa recuerdos perturbadores mediante estimulación bilateral, reduciendo su carga emocional.","cuando_usar":"Recuerdos traumáticos no resueltos — requiere derivación a profesional certificado."},{"id":"b023","modulo":"bienestar","nombre":"Experiencia Somática","autor":"Peter Levine","anio":1997,"resumen":"Trabaja las sensaciones corporales asociadas al trauma para completar respuestas de defensa incompletas.","cuando_usar":"Malestar corporal persistente sin causa médica clara, tras eventos de alto estrés."},{"id":"b024","modulo":"bienestar","nombre":"Autocompasión","autor":"Kristin Neff","anio":2003,"resumen":"Entrena tratarse con la misma amabilidad que se ofrecería a un amigo, reconociendo la humanidad compartida del sufrimiento.","cuando_usar":"Autocrítica severa, perfeccionismo, culpa desproporcionada."},{"id":"b025","modulo":"bienestar","nombre":"Modelo de Regulación Emocional","autor":"James Gross","anio":1998,"resumen":"Describe cinco puntos de intervención (selección de situación, modificación, atención, cambio cognitivo, respuesta) para regular una emoción.","cuando_usar":"Explosiones emocionales, dificultad para gestionar la intensidad de una emoción."},{"id":"b026","modulo":"bienestar","nombre":"Teoría del Apego","autor":"John Bowlby, Mary Ainsworth","anio":1969,"resumen":"Explica cómo los patrones de vínculo temprano influyen en la forma de relacionarse y regular emociones en la adultez.","cuando_usar":"Patrones repetitivos en relaciones, miedo al abandono o a la intimidad."},{"id":"b027","modulo":"bienestar","nombre":"Reestructuración Cognitiva","autor":"Aaron Beck (desarrollo dentro de la TCC)","anio":1970,"resumen":"Proceso guiado para identificar una distorsión cognitiva (ej. pensamiento todo-o-nada) y sustituirla por una interpretación equilibrada.","cuando_usar":"Pensamientos automáticos negativos recurrentes ante una situación concreta."},{"id":"b028","modulo":"bienestar","nombre":"Modelo Job Demands-Resources (JD-R)","autor":"Arnold Bakker, Evangelia Demerouti","anio":2001,"resumen":"Explica el burnout como desequilibrio entre las demandas del puesto y los recursos disponibles para afrontarlas.","cuando_usar":"Diagnóstico de causas de agotamiento laboral y priorización de qué recurso reforzar."},{"id":"b029","modulo":"bienestar","nombre":"Modelo de Burnout de Maslach","autor":"Christina Maslach","anio":1981,"resumen":"Define el burnout en tres dimensiones: agotamiento emocional, despersonalización y baja realización personal.","cuando_usar":"Sospecha de burnout, para identificar en qué dimensión está el mayor impacto."},{"id":"b030","modulo":"bienestar","nombre":"Higiene del Sueño","autor":"Basada en guías clínicas de medicina del sueño","anio":1977,"resumen":"Conjunto de hábitos (horarios, luz, cafeína, pantallas) que favorecen un sueño reparador.","cuando_usar":"Insomnio leve, sueño de mala calidad asociado a hábitos."},{"id":"b031","modulo":"bienestar","nombre":"Escritura Expresiva","autor":"James Pennebaker","anio":1986,"resumen":"Escribir libremente sobre una experiencia emocional durante varios días consecutivos reduce su impacto fisiológico y psicológico.","cuando_usar":"Necesidad de procesar un evento difícil, dificultad para verbalizarlo en voz alta."},{"id":"b032","modulo":"bienestar","nombre":"Aceptación Radical","autor":"Tara Brach / integrada en DBT de Marsha Linehan","anio":2003,"resumen":"Aceptar plenamente una realidad dolorosa que no se puede cambiar, para dejar de sufrir por resistirse a ella.","cuando_usar":"Situaciones irreversibles (despido, diagnóstico, pérdida) generando sufrimiento añadido por la resistencia."},{"id":"b033","modulo":"bienestar","nombre":"Modelo Cognitivo de la Ansiedad","autor":"David M. Clark","anio":1986,"resumen":"Explica cómo la interpretación catastrofista de sensaciones corporales mantiene y amplifica la ansiedad.","cuando_usar":"Ansiedad ante síntomas físicos (taquicardia, mareo) sin causa médica."},{"id":"b034","modulo":"bienestar","nombre":"Terapia de Exposición","autor":"Basada en el condicionamiento clásico, Joseph Wolpe","anio":1958,"resumen":"Exposición gradual y controlada a lo que genera miedo para reducir la respuesta de evitación.","cuando_usar":"Evitación de situaciones concretas (hablar en público, volar) por miedo anticipatorio."},{"id":"b035","modulo":"bienestar","nombre":"Journaling Terapéutico","autor":"Práctica derivada de la escritura expresiva de Pennebaker","anio":1990,"resumen":"Registro diario y estructurado de pensamientos y emociones para ganar perspectiva y detectar patrones.","cuando_usar":"Dificultad para identificar qué desencadena el malestar recurrente."},{"id":"b036","modulo":"bienestar","nombre":"Técnica de la Silla Vacía","autor":"Fritz Perls (Terapia Gestalt)","anio":1951,"resumen":"Dialogar imaginariamente con una persona ausente o una parte de uno mismo para resolver un conflicto emocional no cerrado.","cuando_usar":"Conversaciones pendientes, conflicto interno no resuelto."},{"id":"b037","modulo":"bienestar","nombre":"Terapia Gestalt","autor":"Fritz Perls, Laura Perls, Paul Goodman","anio":1951,"resumen":"Trabaja el 'aquí y ahora', integrando pensamiento, emoción y cuerpo para cerrar asuntos inconclusos.","cuando_usar":"Desconexión entre lo que se siente y lo que se expresa."},{"id":"b038","modulo":"bienestar","nombre":"Logoterapia","autor":"Viktor Frankl","anio":1946,"resumen":"Centra la recuperación en encontrar sentido, incluso en circunstancias adversas, como motor de resiliencia.","cuando_usar":"Sensación de vacío o falta de propósito, crisis existenciales."},{"id":"b039","modulo":"bienestar","nombre":"Modelo Biopsicosocial","autor":"George Engel","anio":1977,"resumen":"Explica el malestar como resultado de la interacción entre factores biológicos, psicológicos y sociales.","cuando_usar":"Malestar con causas mixtas (salud física, contexto laboral, estado emocional)."},{"id":"b040","modulo":"bienestar","nombre":"Terapia Centrada en la Compasión (CFT)","autor":"Paul Gilbert","anio":2009,"resumen":"Entrena el sistema de calma y afiliación para contrarrestar la autocrítica y la vergüenza excesivas.","cuando_usar":"Vergüenza, autocrítica intensa, dificultad para recibir apoyo."},{"id":"b041","modulo":"bienestar","nombre":"Mindfulness para el Dolor y el Malestar Crónico","autor":"Jon Kabat-Zinn (aplicación clínica de MBSR)","anio":1982,"resumen":"Aplica la atención plena a la relación con el malestar físico o emocional persistente, reduciendo el sufrimiento añadido.","cuando_usar":"Malestar físico o emocional de larga duración sin solución inmediata."},{"id":"b042","modulo":"bienestar","nombre":"Modelo de las Etapas del Duelo","autor":"Elisabeth Kübler-Ross","anio":1969,"resumen":"Describe fases habituales (negación, ira, negociación, tristeza, aceptación) que ayudan a normalizar el proceso de pérdida.","cuando_usar":"Duelo por pérdida personal, laboral o de un proyecto importante."},{"id":"b043","modulo":"bienestar","nombre":"Modelo de Resiliencia","autor":"Boris Cyrulnik / Ann Masten","anio":1999,"resumen":"Explica la resiliencia como proceso ordinario y entrenable, no como rasgo excepcional, apoyado en factores protectores.","cuando_usar":"Recuperación tras una adversidad, refuerzo de recursos personales."},{"id":"b044","modulo":"bienestar","nombre":"Técnica STOP","autor":"Práctica derivada de programas de mindfulness clínico","anio":1990,"resumen":"Parar, respirar, observar y proceder: pausa breve para interrumpir una reacción automática ante el estrés.","cuando_usar":"Reacciones impulsivas, necesidad de una pausa rápida en medio de la jornada."},{"id":"b045","modulo":"bienestar","nombre":"Body Scan","autor":"Jon Kabat-Zinn","anio":1979,"resumen":"Recorrido mental de atención por el cuerpo para reconectar con las sensaciones físicas y soltar tensión.","cuando_usar":"Desconexión del cuerpo, tensión física acumulada, dificultad para relajarse."},{"id":"b046","modulo":"bienestar","nombre":"Modelo ABC de Ellis","autor":"Albert Ellis","anio":1957,"resumen":"Descompone una reacción emocional en Evento Activador, Creencia y Consecuencia, para intervenir sobre la creencia.","cuando_usar":"Reacciones emocionales desproporcionadas ante un hecho concreto."},{"id":"b047","modulo":"bienestar","nombre":"Bienestar Subjetivo (SWB)","autor":"Ed Diener","anio":1984,"resumen":"Mide el bienestar a partir de la satisfacción vital, el afecto positivo y la ausencia de afecto negativo.","cuando_usar":"Evaluación general de cómo está la persona más allá de un problema puntual."},{"id":"b048","modulo":"bienestar","nombre":"Técnica de Reetiquetado Cognitivo","autor":"Desarrollo aplicado de la TCC de Beck","anio":1976,"resumen":"Sustituye una etiqueta negativa global ('soy un desastre') por una descripción específica y menos generalizadora del hecho concreto.","cuando_usar":"Autoetiquetado negativo tras un error o fallo puntual."},{"id":"b049","modulo":"bienestar","nombre":"Modelo de Conservación de Recursos (COR)","autor":"Stevan Hobfoll","anio":1989,"resumen":"Explica el estrés como resultado de la pérdida real o percibida de recursos valorados (tiempo, energía, apoyo).","cuando_usar":"Sensación de sobrecarga por acumulación de exigencias sin recursos suficientes."},{"id":"b050","modulo":"bienestar","nombre":"Modelo Cognitivo-Conductual del Insomnio (TCC-I)","autor":"Charles Morin","anio":1993,"resumen":"Adapta la TCC específicamente a los pensamientos y hábitos que perpetúan el insomnio.","cuando_usar":"Insomnio persistente asociado a preocupación por no dormir."},{"id":"c001","modulo":"coaching","nombre":"Modelo GROW","autor":"John Whitmore","anio":1992,"resumen":"Estructura la conversación en cuatro fases: Goal (objetivo), Reality (realidad), Options (opciones) y Will (voluntad de actuar).","cuando_usar":"Punto de partida estándar para cualquier conversación de coaching orientada a la acción."},{"id":"c002","modulo":"coaching","nombre":"Coaching Co-Activo","autor":"Henry Kimsey-House, Karen Kimsey-House","anio":1998,"resumen":"Aborda a la persona completa, no solo el problema, equilibrando el foro (contexto vital) y el fulcro (punto de apoyo para el cambio).","cuando_usar":"Cuando el reto profesional está entrelazado con valores o vida personal."},{"id":"c003","modulo":"coaching","nombre":"Modelo OSKAR","autor":"Mark McKergow, Paul Z. Jackson","anio":2002,"resumen":"Outcome, Scaling, Know-how, Affirm, Review: coaching breve centrado en soluciones y en el progreso ya conseguido.","cuando_usar":"Conversaciones cortas donde se necesita avanzar rápido hacia una acción concreta."},{"id":"c004","modulo":"coaching","nombre":"Modelo CLEAR","autor":"Peter Hawkins","anio":1985,"resumen":"Contract, Listen, Explore, Action, Review: enfatiza el contrato inicial y la revisión final de la sesión.","cuando_usar":"Sesiones de coaching donde conviene fijar expectativas claras desde el inicio."},{"id":"c005","modulo":"coaching","nombre":"Las 4 Disciplinas de la Ejecución","autor":"Chris McChesney, Sean Covey, Jim Huling","anio":2012,"resumen":"Enfocarse en lo crucialmente importante, actuar sobre medidas predictivas, llevar un marcador visible y crear cadencia de rendición de cuentas.","cuando_usar":"Ejecución de objetivos de equipo en medio de muchas prioridades urgentes."},{"id":"c006","modulo":"coaching","nombre":"Feedback SBI (Situación-Comportamiento-Impacto)","autor":"Center for Creative Leadership","anio":1970,"resumen":"Estructura el feedback describiendo la situación concreta, el comportamiento observado y su impacto, evitando juicios de carácter.","cuando_usar":"Dar feedback correctivo o de reconocimiento de forma específica y no acusatoria."},{"id":"c007","modulo":"coaching","nombre":"Radical Candor","autor":"Kim Scott","anio":2017,"resumen":"Combina reto directo con cuidado personal genuino como base de un feedback honesto y efectivo.","cuando_usar":"Managers que evitan el conflicto o que son directos sin empatía."},{"id":"c008","modulo":"coaching","nombre":"Liderazgo Situacional","autor":"Paul Hersey, Ken Blanchard","anio":1969,"resumen":"Adapta el estilo de liderazgo (dirigir, entrenar, apoyar, delegar) al nivel de competencia y compromiso de cada colaborador.","cuando_usar":"Definir cuánto acompañamiento necesita una persona concreta en una tarea concreta."},{"id":"c009","modulo":"coaching","nombre":"Inteligencia Emocional en el Liderazgo","autor":"Daniel Goleman","anio":1995,"resumen":"Identifica autoconciencia, autorregulación, motivación, empatía y habilidades sociales como pilares del liderazgo eficaz.","cuando_usar":"Dificultades de liderazgo relacionadas con la gestión de las propias emociones o las del equipo."},{"id":"c010","modulo":"coaching","nombre":"Los 5 Lenguajes del Aprecio en el Trabajo","autor":"Gary Chapman, Paul White","anio":2011,"resumen":"Identifica cómo prefiere cada persona recibir reconocimiento: palabras, tiempo, servicio, regalos o contacto físico apropiado.","cuando_usar":"Reconocimiento de equipo que no está teniendo el efecto motivador esperado."},{"id":"c011","modulo":"coaching","nombre":"Las 5 Disfunciones de un Equipo","autor":"Patrick Lencioni","anio":2002,"resumen":"Modela la falta de confianza, miedo al conflicto, falta de compromiso, evitación de responsabilidad y falta de resultados como cadena causal.","cuando_usar":"Diagnóstico de por qué un equipo no rinde a pesar de tener buen talento."},{"id":"c012","modulo":"coaching","nombre":"Comunicación No Violenta (CNV)","autor":"Marshall Rosenberg","anio":1970,"resumen":"Estructura la comunicación en observación, sentimiento, necesidad y petición, evitando juicios y exigencias.","cuando_usar":"Conversaciones difíciles o con carga emocional alta entre compañeros."},{"id":"c013","modulo":"coaching","nombre":"Modelo DISC","autor":"William Moulton Marston","anio":1928,"resumen":"Clasifica estilos de comportamiento en Dominancia, Influencia, Estabilidad y Cumplimiento para adaptar la comunicación.","cuando_usar":"Conflictos de estilo de comunicación entre miembros de un equipo."},{"id":"c014","modulo":"coaching","nombre":"CliftonStrengths (Fortalezas Gallup)","autor":"Don Clifton","anio":1998,"resumen":"Identifica los talentos naturales dominantes de una persona para desarrollarlos en vez de centrarse solo en corregir debilidades.","cuando_usar":"Planificación de desarrollo profesional centrada en fortalezas."},{"id":"c015","modulo":"coaching","nombre":"Liderazgo Transformacional","autor":"Bernard Bass","anio":1985,"resumen":"Describe un liderazgo que inspira mediante visión, estimulación intelectual y atención individualizada, más allá del intercambio transaccional.","cuando_usar":"Necesidad de motivar a un equipo más allá de incentivos concretos."},{"id":"c016","modulo":"coaching","nombre":"Liderazgo Auténtico","autor":"Bill George","anio":2003,"resumen":"Defiende liderar desde los valores propios, la autoconciencia y la coherencia, en vez de imitar un modelo externo.","cuando_usar":"Managers que sienten que están 'actuando un papel' que no encaja con ellos."},{"id":"c017","modulo":"coaching","nombre":"Objetivos SMART","autor":"George T. Doran (popularizado por Peter Drucker)","anio":1981,"resumen":"Un objetivo eficaz debe ser específico, medible, alcanzable, relevante y con plazo definido.","cuando_usar":"Definición de cualquier objetivo profesional o de equipo."},{"id":"c018","modulo":"coaching","nombre":"OKR (Objectives and Key Results)","autor":"Andy Grove (popularizado por John Doerr)","anio":1970,"resumen":"Define un objetivo cualitativo ambicioso junto a resultados clave medibles que indican si se ha alcanzado.","cuando_usar":"Alineación de objetivos de equipo con la estrategia de la empresa."},{"id":"c019","modulo":"coaching","nombre":"Feedback 360","autor":"Desarrollo colectivo en gestión de RRHH","anio":1950,"resumen":"Recoge feedback de superiores, iguales y colaboradores para obtener una visión completa del desempeño de una persona.","cuando_usar":"Evaluaciones de desarrollo de liderazgo con perspectiva múltiple."},{"id":"c020","modulo":"coaching","nombre":"Conversaciones Difíciles","autor":"Douglas Stone, Bruce Patton, Sheila Heen","anio":1999,"resumen":"Distingue tres conversaciones simultáneas (los hechos, los sentimientos, la identidad) presentes en cualquier conflicto difícil.","cuando_usar":"Preparación para una conversación de feedback duro o un desacuerdo importante."},{"id":"c021","modulo":"coaching","nombre":"Conversaciones Cruciales","autor":"Kerry Patterson, Joseph Grenny, Ron McMillan, Al Switzler","anio":2002,"resumen":"Técnicas para mantener el diálogo abierto en momentos de alto riesgo, opiniones opuestas y emociones fuertes.","cuando_usar":"Discrepancias importantes donde el silencio o la agresividad son la reacción habitual."},{"id":"c022","modulo":"coaching","nombre":"Método de Negociación de Harvard","autor":"Roger Fisher, William Ury","anio":1981,"resumen":"Negociación basada en intereses (no en posiciones), separando a las personas del problema y buscando opciones de beneficio mutuo.","cuando_usar":"Negociaciones internas de recursos, condiciones o desacuerdos de equipo."},{"id":"c023","modulo":"coaching","nombre":"Los 7 Hábitos de la Gente Altamente Efectiva","autor":"Stephen Covey","anio":1989,"resumen":"Principios de efectividad personal y de liderazgo como la proactividad, empezar con el fin en mente y buscar primero comprender.","cuando_usar":"Desarrollo general de hábitos de efectividad y liderazgo."},{"id":"c024","modulo":"coaching","nombre":"Mindset de Crecimiento","autor":"Carol Dweck","anio":2006,"resumen":"Distingue entre una mentalidad fija (el talento es innato) y una de crecimiento (las capacidades se desarrollan con esfuerzo).","cuando_usar":"Miedo al fracaso, resistencia a asumir retos nuevos."},{"id":"c025","modulo":"coaching","nombre":"Estado de Flow","autor":"Mihaly Csikszentmihalyi","anio":1975,"resumen":"Describe el estado de máxima concentración y disfrute cuando el reto de una tarea encaja con la habilidad de la persona.","cuando_usar":"Diseño de tareas o rediseño de puesto para aumentar el compromiso."},{"id":"c026","modulo":"coaching","nombre":"Coaching Ontológico","autor":"Fernando Flores, Rafael Echeverría","anio":1990,"resumen":"Trabaja sobre el lenguaje, las emociones y el cuerpo como los tres dominios que constituyen la forma de observar y actuar de una persona.","cuando_usar":"Patrones de comportamiento repetidos que no cambian solo con más información."},{"id":"c027","modulo":"coaching","nombre":"Modelo TGROW","autor":"Extensión de John Whitmore","anio":1992,"resumen":"Añade la fase Topic (tema) antes del modelo GROW para clarificar de qué se va a hablar exactamente en la sesión.","cuando_usar":"Cuando el tema de la conversación no está claro al empezar."},{"id":"c028","modulo":"coaching","nombre":"Indagación Apreciativa (Appreciative Inquiry)","autor":"David Cooperrider","anio":1987,"resumen":"Enfoca el cambio organizacional o personal a partir de lo que ya funciona bien, en vez de partir del problema.","cuando_usar":"Procesos de cambio donde el enfoque en problemas ha generado desmotivación."},{"id":"c029","modulo":"coaching","nombre":"Análisis Transaccional","autor":"Eric Berne","anio":1958,"resumen":"Analiza la interacción entre los estados del yo (Padre, Adulto, Niño) para entender patrones de comunicación disfuncionales.","cuando_usar":"Conflictos recurrentes de comunicación con un patrón que se repite."},{"id":"c030","modulo":"coaching","nombre":"Matriz de Eisenhower","autor":"Atribuida a Dwight D. Eisenhower, formalizada por Stephen Covey","anio":1954,"resumen":"Clasifica tareas según urgencia e importancia para priorizar el foco del tiempo y la energía.","cuando_usar":"Sobrecarga de tareas, dificultad para priorizar."},{"id":"c031","modulo":"coaching","nombre":"Niveles de Delegación","autor":"Desarrollo en gestión de equipos, popularizado por Ken Blanchard","anio":1985,"resumen":"Define un gradiente desde 'hazlo tú' hasta 'decide tú' para delegar con el nivel de autonomía adecuado.","cuando_usar":"Managers que delegan poco o delegan sin dar suficiente contexto."},{"id":"c032","modulo":"coaching","nombre":"Teoría de los Dos Factores de Herzberg","autor":"Frederick Herzberg","anio":1959,"resumen":"Distingue factores higiénicos (evitan la insatisfacción) de factores motivadores (generan compromiso real).","cuando_usar":"Diagnóstico de por qué mejorar condiciones no aumenta el compromiso del equipo."},{"id":"c033","modulo":"coaching","nombre":"Teoría X e Y","autor":"Douglas McGregor","anio":1960,"resumen":"Contrasta dos supuestos sobre las personas en el trabajo (necesitan control vs. buscan responsabilidad) que moldean el estilo de gestión.","cuando_usar":"Revisión de las creencias de fondo de un manager sobre su equipo."},{"id":"c034","modulo":"coaching","nombre":"Etapas de Formación de Equipos (Tuckman)","autor":"Bruce Tuckman","anio":1965,"resumen":"Describe las fases Forming, Storming, Norming, Performing por las que pasa un equipo nuevo o reconfigurado.","cuando_usar":"Equipos de nueva formación o con cambios recientes de miembros."},{"id":"c035","modulo":"coaching","nombre":"Coaching Sistémico","autor":"Peter Hawkins","anio":2005,"resumen":"Sitúa a la persona dentro de su sistema (equipo, organización) y trabaja las relaciones, no solo al individuo aislado.","cuando_usar":"El reto de la persona está muy condicionado por la dinámica de su equipo u organización."},{"id":"c036","modulo":"coaching","nombre":"Ciclo de Aprendizaje Experiencial","autor":"David Kolb","anio":1984,"resumen":"Describe el aprendizaje como un ciclo de experiencia concreta, observación reflexiva, conceptualización y experimentación activa.","cuando_usar":"Diseño de planes de desarrollo basados en la experiencia real, no solo en teoría."},{"id":"c037","modulo":"coaching","nombre":"Modelo de Cambio de 8 Pasos","autor":"John Kotter","anio":1995,"resumen":"Secuencia de pasos (crear urgencia, formar coalición, comunicar visión...) para liderar un cambio organizacional exitoso.","cuando_usar":"Liderar un cambio de equipo, proceso o reestructuración."},{"id":"c038","modulo":"coaching","nombre":"Modelo ADKAR","autor":"Jeff Hiatt (Prosci)","anio":2003,"resumen":"Awareness, Desire, Knowledge, Ability, Reinforcement: modelo de gestión del cambio centrado en la persona, no en el proceso.","cuando_usar":"Resistencia individual a un cambio impuesto desde la organización."},{"id":"c039","modulo":"coaching","nombre":"Liderazgo de Servicio","autor":"Robert Greenleaf","anio":1970,"resumen":"Plantea que el líder existe primero para servir al desarrollo de su equipo, y solo después para dirigir.","cuando_usar":"Managers con estilo muy jerárquico que buscan un enfoque más colaborativo."},{"id":"c040","modulo":"coaching","nombre":"Anclas de Carrera","autor":"Edgar Schein","anio":1978,"resumen":"Identifica el valor o motivación central (técnica, gestión, autonomía, seguridad...) que guía las decisiones de carrera de una persona.","cuando_usar":"Decisiones de cambio de rol, promoción o reorientación profesional."},{"id":"c041","modulo":"coaching","nombre":"Ikigai","autor":"Tradición japonesa, sistematizada por Héctor García y Francesc Miralles","anio":2016,"resumen":"Marco que cruza lo que se ama, en lo que se es bueno, lo que el mundo necesita y lo que se puede monetizar para encontrar propósito.","cuando_usar":"Búsqueda de sentido o reorientación vocacional."},{"id":"c042","modulo":"coaching","nombre":"Job Crafting","autor":"Amy Wrzesniewski, Jane Dutton","anio":2001,"resumen":"Rediseñar activamente tareas, relaciones o percepción del propio puesto para aumentar su sentido y encaje personal.","cuando_usar":"Insatisfacción con el puesto actual sin posibilidad de cambiarlo por completo."},{"id":"c043","modulo":"coaching","nombre":"Design Thinking aplicado al desarrollo profesional","autor":"IDEO / Stanford d.school (adaptado por Bill Burnett y Dave Evans)","anio":2016,"resumen":"Aplica el proceso de empatizar, definir, idear, prototipar y testear al diseño de la propia carrera profesional.","cuando_usar":"Indecisión vocacional, exploración de alternativas de carrera."},{"id":"c044","modulo":"coaching","nombre":"Teoría del Establecimiento de Metas","autor":"Edwin Locke, Gary Latham","anio":1968,"resumen":"Demuestra que metas específicas y desafiantes generan mejor desempeño que metas vagas o poco exigentes.","cuando_usar":"Definición de metas de desarrollo individual poco concretas."},{"id":"c045","modulo":"coaching","nombre":"Método WOOP","autor":"Gabriele Oettingen","anio":2001,"resumen":"Wish, Outcome, Obstacle, Plan: combina visualización positiva con planificación realista de obstáculos.","cuando_usar":"Objetivos que se quedan solo en intención sin traducirse en acción."},{"id":"c046","modulo":"coaching","nombre":"Peer Coaching","autor":"Desarrollo colectivo en formación de adultos","anio":1980,"resumen":"Estructura conversaciones de coaching entre personas del mismo nivel jerárquico, sin relación de autoridad.","cuando_usar":"Cuando conviene una perspectiva de igual a igual, sin jerarquía de por medio."},{"id":"c047","modulo":"coaching","nombre":"Feedforward","autor":"Marshall Goldsmith","anio":2002,"resumen":"En vez de dar feedback sobre el pasado, se piden sugerencias concretas orientadas a mejorar en el futuro.","cuando_usar":"Personas que se ponen a la defensiva ante el feedback tradicional."},{"id":"c048","modulo":"coaching","nombre":"Toma de Decisiones Racional-Emocional","autor":"Desarrollo integrador basado en Daniel Kahneman y Antonio Damasio","anio":2000,"resumen":"Reconoce que las decisiones combinan análisis racional y señales emocionales, y entrena a integrarlas conscientemente.","cuando_usar":"Bloqueo ante una decisión importante por conflicto entre lógica y sensación."},{"id":"c049","modulo":"coaching","nombre":"Modelo de Competencias ICF","autor":"International Coaching Federation","anio":1995,"resumen":"Define competencias clave del coaching profesional: escucha activa, generar conciencia, facilitar el crecimiento del cliente.","cuando_usar":"Marco de referencia general de cómo debe conducirse cualquier sesión de coaching."},{"id":"c050","modulo":"coaching","nombre":"Modelo de las Tres Preguntas","autor":"John Whitmore","anio":1992,"resumen":"Simplifica cualquier sesión a tres preguntas: ¿qué quieres lograr?, ¿dónde estás ahora?, ¿qué vas a hacer?","cuando_usar":"Conversaciones muy breves donde no hay tiempo para el modelo GROW completo."},{"id":"b051","modulo":"bienestar","nombre":"Fenómeno del Impostor","autor":"Pauline Clance, Suzanne Imes","anio":1978,"resumen":"Describe la sensación persistente de no merecer los propios logros y el miedo a ser 'descubierto' como un fraude, pese a la evidencia de competencia.","cuando_usar":"Dudas sobre la propia valía profesional a pesar de resultados objetivos."},{"id":"b052","modulo":"bienestar","nombre":"Teoría de la Apreciación Cognitiva del Estrés","autor":"Richard Lazarus, Susan Folkman","anio":1984,"resumen":"Explica la ansiedad anticipatoria como resultado de una evaluación (appraisal) de amenaza que supera los recursos percibidos para afrontarla.","cuando_usar":"Anticipar lo peor antes de una reunión o evento importante."},{"id":"b053","modulo":"bienestar","nombre":"Teoría de la Autoeficacia","autor":"Albert Bandura","anio":1977,"resumen":"La creencia en la propia capacidad para lograr una tarea predice el desempeño más que la habilidad real en sí misma.","cuando_usar":"No sentirse capaz de un rol nuevo, aunque se tenga la competencia objetiva."},{"id":"b054","modulo":"bienestar","nombre":"Teoría de los Estilos de Respuesta (Rumiación)","autor":"Susan Nolen-Hoeksema","anio":1991,"resumen":"Explica cómo dar vueltas repetidamente a un problema sin pasar a la acción mantiene y agrava el malestar emocional.","cuando_usar":"No poder dejar de darle vueltas a algo sin llegar a ninguna conclusión."},{"id":"b055","modulo":"bienestar","nombre":"Modelo de Transición de Bridges","autor":"William Bridges","anio":1991,"resumen":"Describe tres fases psicológicas del cambio: el final (soltar), la zona neutra (incertidumbre) y el nuevo comienzo.","cuando_usar":"Gestionar un cambio no elegido — despido, reestructuración, cambio de equipo."},{"id":"b056","modulo":"bienestar","nombre":"Granularidad Emocional","autor":"Lisa Feldman Barrett","anio":2004,"resumen":"La capacidad de nombrar emociones con precisión (en vez de 'mal' o 'estresado') mejora la regulación emocional.","cuando_usar":"Dificultad para identificar exactamente qué se está sintiendo."},{"id":"b057","modulo":"bienestar","nombre":"Investigación sobre la Gratitud","autor":"Robert Emmons","anio":2003,"resumen":"Practicar el registro consciente de la gratitud reduce el afecto negativo y aumenta el bienestar subjetivo a corto plazo.","cuando_usar":"Antídoto breve contra el cinismo o el desgaste del día a día."},{"id":"b058","modulo":"bienestar","nombre":"Estilo Explicativo","autor":"Martin Seligman","anio":1990,"resumen":"Distingue un estilo explicativo pesimista (permanente, generalizado, personal) de uno optimista al interpretar los fracasos propios.","cuando_usar":"Explicar los propios fracasos de forma desproporcionada o generalizada."},{"id":"b059","modulo":"bienestar","nombre":"Efecto Zeigarnik","autor":"Bluma Zeigarnik","anio":1927,"resumen":"Las tareas inacabadas ocupan más espacio mental que las terminadas, generando una sensación difusa de sobrecarga.","cuando_usar":"Dificultad para desconectar por tareas pendientes sin cerrar."},{"id":"b060","modulo":"bienestar","nombre":"Modelo SCARF","autor":"David Rock","anio":2008,"resumen":"Identifica cinco dominios (Estatus, Certeza, Autonomía, Relación, Justicia) que activan amenaza o recompensa social en el cerebro.","cuando_usar":"Explicar por qué un cambio pequeño mal comunicado genera una reacción desproporcionada."},{"id":"b061","modulo":"bienestar","nombre":"Triángulo Dramático de Karpman","autor":"Stephen Karpman","anio":1968,"resumen":"Describe el patrón relacional entre Víctima, Perseguidor y Rescatador que perpetúa un conflicto sin resolverlo.","cuando_usar":"Cargar constantemente con los problemas del equipo como 'rescatador'."},{"id":"b062","modulo":"bienestar","nombre":"Investigación sobre la Vulnerabilidad","autor":"Brené Brown","anio":2010,"resumen":"Muestra que mostrarse vulnerable, incluyendo pedir ayuda, se percibe como fortaleza y no como debilidad.","cuando_usar":"Dificultad para pedir ayuda por miedo a parecer incompetente."},{"id":"b063","modulo":"bienestar","nombre":"Perfeccionismo Multidimensional","autor":"Paul Hewitt, Gordon Flett","anio":1991,"resumen":"Distingue perfeccionismo autoimpuesto, orientado a otros y socialmente prescrito como fuentes distintas de autoexigencia.","cuando_usar":"Sensación de que nunca es suficiente pese a los resultados obtenidos."},{"id":"b064","modulo":"bienestar","nombre":"Teoría de la Justicia Organizacional","autor":"Jerald Greenberg","anio":1987,"resumen":"Distingue justicia distributiva, procedimental e interpersonal como dimensiones que determinan si un proceso se percibe como justo.","cuando_usar":"Evaluaciones de desempeño que se perciben como injustas."},{"id":"b065","modulo":"bienestar","nombre":"Áreas de la Vida Laboral","autor":"Christina Maslach, Michael Leiter","anio":1997,"resumen":"Identifica seis áreas de desajuste (carga, control, recompensa, comunidad, justicia, valores) que predicen el burnout antes de que aparezca.","cuando_usar":"Detectar señales tempranas de burnout antes de llegar al agotamiento."},{"id":"b066","modulo":"bienestar","nombre":"Ley de Yerkes-Dodson","autor":"Robert Yerkes, John Dodson","anio":1908,"resumen":"Relaciona el nivel de activación (arousal) con el rendimiento en forma de U invertida: ni muy poco ni demasiado estrés optimizan el desempeño.","cuando_usar":"Gestionar la ansiedad antes de una presentación importante."},{"id":"b067","modulo":"bienestar","nombre":"Modelo de Hiperactivación del Insomnio","autor":"Michael Perlis","anio":1997,"resumen":"Explica el insomnio persistente como un estado de activación fisiológica y cognitiva elevada, más allá de los malos hábitos de sueño.","cuando_usar":"Dormir mal pese a sentirse agotado."},{"id":"b068","modulo":"bienestar","nombre":"Autocompasión Aplicada al Trabajo","autor":"Kristin Neff, Christopher Germer","anio":2013,"resumen":"Adapta el entrenamiento en autocompasión a contextos de rendimiento y evaluación laboral.","cuando_usar":"Recuperarse de un día realmente malo en el trabajo."},{"id":"b069","modulo":"bienestar","nombre":"Modelo de Vergüenza y Culpa","autor":"June Tangney","anio":2002,"resumen":"Distingue la culpa adaptativa (centrada en el acto: 'hice algo mal') de la vergüenza destructiva (centrada en el yo: 'soy malo').","cuando_usar":"Culpa persistente que no se suelta tras un error."},{"id":"b070","modulo":"bienestar","nombre":"Primeros Auxilios en Salud Mental","autor":"Betty Kitchener, Anthony Jorm","anio":2000,"resumen":"Protocolo para reconocer señales de malestar en otra persona y ofrecer apoyo inicial antes de derivar a ayuda profesional.","cuando_usar":"Acompañar a un compañero que lo está pasando mal, sin saber cómo ayudar."},{"id":"b071","modulo":"bienestar","nombre":"Modelo de Establecimiento de Límites","autor":"Henry Cloud, John Townsend","anio":1992,"resumen":"Marco para poner límites saludables sin culpa, distinguiendo responsabilidad propia de la ajena.","cuando_usar":"Poner un límite sin sentir que se está siendo una mala persona."},{"id":"b072","modulo":"bienestar","nombre":"Jerarquía de Necesidades","autor":"Abraham Maslow","anio":1943,"resumen":"Ordena las necesidades humanas desde las fisiológicas hasta la autorrealización, útil para diagnosticar qué nivel está desatendido.","cuando_usar":"Diagnóstico general de qué necesidad básica está sin cubrir antes de abordar aspiraciones mayores."},{"id":"b073","modulo":"bienestar","nombre":"Optimismo Aprendido","autor":"Martin Seligman","anio":1991,"resumen":"Entrena a disputar activamente los pensamientos pesimistas automáticos para desarrollar un estilo explicativo más adaptativo.","cuando_usar":"Patrón repetido de anticipar el fracaso antes de intentar algo."},{"id":"b074","modulo":"bienestar","nombre":"Fatiga por Compasión","autor":"Charles Figley","anio":1995,"resumen":"Describe el desgaste emocional de quienes cuidan o apoyan constantemente a otros, con síntomas similares al burnout.","cuando_usar":"Managers o compañeros que apoyan mucho a otros y se sienten agotados por ello."},{"id":"b075","modulo":"bienestar","nombre":"Síndrome General de Adaptación","autor":"Hans Selye","anio":1936,"resumen":"Describe tres fases fisiológicas ante el estrés sostenido: alarma, resistencia y agotamiento.","cuando_usar":"Explicar por qué el estrés mantenido en el tiempo termina pasando factura física."},{"id":"b076","modulo":"bienestar","nombre":"Regulación Emocional Interpersonal","autor":"John Gottman","anio":1994,"resumen":"Identifica patrones de comunicación (críticas, desprecio, actitud defensiva, evasión) que erosionan una relación si no se corrigen.","cuando_usar":"Conflicto de relación sostenido con un compañero o superior."},{"id":"b077","modulo":"bienestar","nombre":"Teoría del Contagio Emocional","autor":"Elaine Hatfield","anio":1993,"resumen":"Explica cómo las emociones se transmiten inconscientemente entre personas a través de la imitación de expresiones y tono.","cuando_usar":"El ambiente emocional de un equipo afecta al estado de ánimo individual."},{"id":"b078","modulo":"bienestar","nombre":"Escala de Estrés de Holmes y Rahe","autor":"Thomas Holmes, Richard Rahe","anio":1967,"resumen":"Cuantifica el impacto acumulado de eventos vitales (cambio de trabajo, mudanza, duelo) sobre el riesgo de enfermar por estrés.","cuando_usar":"Varios cambios vitales importantes ocurriendo a la vez."},{"id":"b079","modulo":"bienestar","nombre":"Teoría Polivagal","autor":"Stephen Porges","anio":1994,"resumen":"Explica cómo el sistema nervioso autónomo alterna entre estados de seguridad, lucha/huida y bloqueo según la percepción de amenaza.","cuando_usar":"Explicar reacciones corporales intensas (bloqueo, taquicardia) ante el estrés."},{"id":"b080","modulo":"bienestar","nombre":"Investigación sobre el Perdón","autor":"Everett Worthington","anio":2001,"resumen":"Modelo REACH (Recordar, Empatizar, dar el regalo Altruista, Comprometerse, Hold/mantener) para procesar un agravio sin negarlo.","cuando_usar":"Resentimiento sostenido hacia un compañero o la propia empresa."},{"id":"b081","modulo":"bienestar","nombre":"Adaptación Hedónica","autor":"Philip Brickman, Donald Campbell","anio":1971,"resumen":"Explica por qué tanto los logros como los reveses pierden intensidad emocional con el tiempo, volviendo a un punto base de bienestar.","cuando_usar":"Sensación de que ningún logro produce satisfacción duradera."},{"id":"b082","modulo":"bienestar","nombre":"Modelo Cognitivo del Perfeccionismo","autor":"Randy Frost","anio":1990,"resumen":"Identifica seis dimensiones del perfeccionismo (estándares personales, dudas, organización, expectativas paternas...) para intervenir sobre la más disfuncional.","cuando_usar":"Perfeccionismo que bloquea la entrega de un trabajo por miedo a que no sea suficiente."},{"id":"b083","modulo":"bienestar","nombre":"Defusión Cognitiva","autor":"Steven Hayes (dentro de ACT)","anio":1999,"resumen":"Técnica para distanciarse de un pensamiento observándolo como un evento mental, no como un hecho literal.","cuando_usar":"Pensamientos negativos muy 'pegajosos' que se viven como verdades absolutas."},{"id":"b084","modulo":"bienestar","nombre":"Modelo Original del Burnout","autor":"Herbert Freudenberger","anio":1974,"resumen":"Primera descripción clínica del agotamiento extremo por sobreimplicación laboral, origen del concepto de burnout.","cuando_usar":"Introducción del concepto de burnout a alguien que no lo conoce."},{"id":"b085","modulo":"bienestar","nombre":"Congruencia Personal","autor":"Carl Rogers","anio":1961,"resumen":"Describe el bienestar como la coherencia entre el yo real y el yo ideal; el malestar surge de la distancia entre ambos.","cuando_usar":"Sensación de estar viviendo o trabajando de forma incoherente con los propios valores."},{"id":"b086","modulo":"bienestar","nombre":"Silencio y Voz en el Trabajo","autor":"Elizabeth Morrison, Frances Milliken","anio":2000,"resumen":"Explica por qué las personas callan problemas o ideas por miedo, aun sabiendo que hablar sería útil para el equipo.","cuando_usar":"Dificultad para expresar una opinión o preocupación en el equipo."},{"id":"b087","modulo":"bienestar","nombre":"Modelo de los Dos Procesos del Sueño","autor":"Alexander Borbély","anio":1982,"resumen":"Explica el sueño como interacción entre la presión homeostática de sueño y el ritmo circadiano interno.","cuando_usar":"Entender por qué los horarios irregulares afectan tanto a la calidad del sueño."},{"id":"b088","modulo":"bienestar","nombre":"Contagio Emocional en Equipos","autor":"Sigal Barsade","anio":2002,"resumen":"Demuestra que el estado de ánimo de una persona en un equipo se propaga y afecta al rendimiento y cohesión del grupo.","cuando_usar":"Impacto del propio estado de ánimo en el ambiente general del equipo."},{"id":"b089","modulo":"bienestar","nombre":"Ventana de Tolerancia","autor":"Dan Siegel","anio":1999,"resumen":"Describe el rango óptimo de activación emocional en el que una persona puede pensar con claridad, fuera de la hiperactivación o el bloqueo.","cuando_usar":"Sentirse desbordado por la ansiedad de forma repentina."},{"id":"b090","modulo":"bienestar","nombre":"Agotamiento del Yo (Ego Depletion)","autor":"Roy Baumeister","anio":1998,"resumen":"Plantea que la fuerza de voluntad es un recurso limitado que se agota con el uso repetido de autocontrol durante el día.","cuando_usar":"Explicar por qué cuesta más autorregularse al final de una jornada exigente."},{"id":"b091","modulo":"bienestar","nombre":"Duelo No Reconocido","autor":"Kenneth Doka","anio":1989,"resumen":"Describe el duelo por pérdidas que la sociedad no valida como tal (perder un puesto, un equipo, un proyecto), y que por eso cuesta más procesar.","cuando_usar":"El duelo de un puesto o equipo que ya no existe."},{"id":"b092","modulo":"bienestar","nombre":"Investigación sobre el Aburrimiento Laboral","autor":"Cynthia Fisher","anio":1993,"resumen":"Estudia el aburrimiento crónico en el trabajo como fuente de malestar tan relevante como la sobrecarga.","cuando_usar":"Falta de motivación por infraestimulación, no por exceso de carga."},{"id":"b093","modulo":"bienestar","nombre":"Modelo del Sentido del Trabajo (Job, Career, Calling)","autor":"Amy Wrzesniewski","anio":1997,"resumen":"Distingue tres orientaciones hacia el trabajo — como obligación, como carrera o como vocación — que predicen la satisfacción laboral.","cuando_usar":"Reflexionar sobre qué relación se tiene realmente con el propio trabajo."},{"id":"b094","modulo":"bienestar","nombre":"Teoría del Contrato Psicológico","autor":"Denise Rousseau","anio":1989,"resumen":"Describe las expectativas implícitas y no escritas entre empleado y empresa, cuya ruptura genera un malestar desproporcionado.","cuando_usar":"Sensación de traición o desencanto tras un cambio en las condiciones no explicitadas."},{"id":"b095","modulo":"bienestar","nombre":"Modelo Cognitivo del Trauma","autor":"Anke Ehlers, David Clark","anio":2000,"resumen":"Explica cómo la interpretación negativa de un evento traumático y su memoria mantienen el malestar en el presente.","cuando_usar":"Recuerdo de un evento laboral difícil que sigue afectando en el presente."},{"id":"b096","modulo":"bienestar","nombre":"Investigación sobre la Soledad","autor":"John Cacioppo","anio":2008,"resumen":"Demuestra que la soledad percibida (no el aislamiento objetivo) tiene un impacto medible en la salud física y mental.","cuando_usar":"Sensación de desconexión pese a estar rodeado de compañeros."},{"id":"b097","modulo":"bienestar","nombre":"Autoamabilidad ante el Fallo","autor":"Kristin Neff","anio":2003,"resumen":"Componente de la autocompasión centrado específicamente en tratarse con amabilidad, no crítica, tras un error concreto.","cuando_usar":"Autocrítica intensa inmediatamente después de cometer un error."},{"id":"b098","modulo":"bienestar","nombre":"Teoría del Umbral de Recuperación","autor":"Sabine Sonnentag","anio":2001,"resumen":"Explica que desconectar psicológicamente del trabajo fuera de horario es necesario para recuperar recursos, no solo dejar de trabajar físicamente.","cuando_usar":"Seguir 'trabajando mentalmente' fuera del horario laboral."},{"id":"b099","modulo":"bienestar","nombre":"Modelo de Afrontamiento Proactivo","autor":"Ralf Schwarzer","anio":1999,"resumen":"Distingue el afrontamiento reactivo (ante un problema ya presente) del proactivo (anticipar y prevenir el estrés futuro).","cuando_usar":"Prevenir el agotamiento antes de que se convierta en una crisis."},{"id":"b100","modulo":"bienestar","nombre":"Teoría del Crecimiento Postraumático","autor":"Richard Tedeschi, Lawrence Calhoun","anio":1996,"resumen":"Describe cómo, tras una crisis, algunas personas desarrollan un cambio positivo en prioridades, relaciones o sentido vital.","cuando_usar":"Buscar sentido o aprendizaje tras superar una etapa laboral muy dura."},{"id":"c051","modulo":"coaching","nombre":"Instrumento de Modos de Conflicto Thomas-Kilmann","autor":"Kenneth Thomas, Ralph Kilmann","anio":1974,"resumen":"Identifica cinco estilos de gestión del conflicto (competir, colaborar, comprometer, evitar, acomodar) según asertividad y cooperación.","cuando_usar":"Dos personas del equipo que no se llevan bien y repiten el mismo patrón de conflicto."},{"id":"c052","modulo":"coaching","nombre":"Seguridad Psicológica","autor":"Amy Edmondson","anio":1999,"resumen":"Define el grado en que un equipo cree que puede tomar riesgos interpersonales (opinar, admitir errores) sin ser castigado por ello.","cuando_usar":"Un equipo no confía todavía en su manager — por dónde empezar a construir confianza."},{"id":"c053","modulo":"coaching","nombre":"El Círculo Dorado","autor":"Simon Sinek","anio":2009,"resumen":"Plantea comunicar primero el 'por qué' (propósito), luego el 'cómo' y por último el 'qué', para generar movimiento real en el equipo.","cuando_usar":"Un equipo no se mueve pese a que el plan es objetivamente bueno."},{"id":"c054","modulo":"coaching","nombre":"Modelo de Decisión Vroom-Yetton","autor":"Victor Vroom, Philip Yetton","anio":1973,"resumen":"Ayuda a decidir cuánto debe involucrarse al equipo en una decisión según su impacto, urgencia y nivel de experiencia requerido.","cuando_usar":"Determinar cuánto se debe consultar al equipo antes de decidir uno mismo."},{"id":"c055","modulo":"coaching","nombre":"Lo Que Te Trajo Hasta Aquí No Te Llevará Hasta Allá","autor":"Marshall Goldsmith","anio":2007,"resumen":"Plantea que los comportamientos que llevaron al éxito en un rol pueden convertirse en un obstáculo en el siguiente nivel de responsabilidad.","cuando_usar":"Un estilo de liderazgo que funcionaba deja de ser efectivo en un rol nuevo."},{"id":"c056","modulo":"coaching","nombre":"La Velocidad de la Confianza","autor":"Stephen M. R. Covey","anio":2006,"resumen":"Plantea que la confianza es un factor medible que acelera (o una falta de ella ralentiza) cualquier proceso de equipo.","cuando_usar":"Diagnosticar por qué los procesos de un equipo van más lentos de lo esperado."},{"id":"c057","modulo":"coaching","nombre":"1:1 Efectivos (Manager Tools)","autor":"Mark Horstman","anio":2004,"resumen":"Estructura de reunión individual semanal centrada en la persona (10 min), la tarea (10 min) y el futuro (10 min), no en un checklist de estado.","cuando_usar":"Preguntar qué tratar en un 1:1 para que no sea un simple checklist de tareas."},{"id":"c058","modulo":"coaching","nombre":"Líderes frente a Gestores","autor":"Warren Bennis","anio":1985,"resumen":"Distingue liderar (marcar dirección, inspirar) de gestionar (planificar, controlar, ejecutar) como funciones complementarias pero distintas.","cuando_usar":"Saber si se está liderando o solo gestionando el día a día."},{"id":"c059","modulo":"coaching","nombre":"Calibración de Desempeño","autor":"Prácticas de gestión del talento en RRHH","anio":1990,"resumen":"Proceso de comparar evaluaciones entre managers para reducir el sesgo individual y hacerlas más consistentes y justas.","cuando_usar":"Dar una evaluación de desempeño sin que se sienta injusta o arbitraria."},{"id":"c060","modulo":"coaching","nombre":"Arquitectura de Decisiones (Nudge)","autor":"Richard Thaler, Cass Sunstein","anio":2008,"resumen":"Muestra cómo pequeños cambios en cómo se presenta una opción influyen en la decisión, sin restringir la libertad de elegir.","cuando_usar":"Un cambio pequeño bien planteado genera mejor reacción que uno grande impuesto."},{"id":"c061","modulo":"coaching","nombre":"Efecto Pigmalión","autor":"Robert Rosenthal, Lenore Jacobson","anio":1968,"resumen":"Demuestra que las expectativas de un líder sobre una persona influyen, sin darse cuenta, en el desempeño real de esa persona.","cuando_usar":"Impacto de las propias expectativas (positivas o negativas) sobre el rendimiento del equipo."},{"id":"c062","modulo":"coaching","nombre":"Las Cuatro Etapas de Competencia","autor":"Noel Burch","anio":1970,"resumen":"Describe el aprendizaje de una habilidad en cuatro fases: incompetencia inconsciente, consciente, competencia consciente e inconsciente.","cuando_usar":"Normalizar la incomodidad de aprender un rol o habilidad nueva."},{"id":"c063","modulo":"coaching","nombre":"Escucha de Nivel 3","autor":"Marco de Coaching Co-Activo","anio":1998,"resumen":"Distingue tres niveles de escucha: centrada en uno mismo, centrada en el otro, y global (incluyendo tono, energía y contexto).","cuando_usar":"Mejorar la calidad de la escucha en conversaciones de feedback o coaching."},{"id":"c064","modulo":"coaching","nombre":"Preguntas Poderosas","autor":"International Coaching Federation","anio":1995,"resumen":"Principio de coaching que prioriza preguntas abiertas que generan reflexión, frente a preguntas cerradas o sugerentes.","cuando_usar":"Marco general para estructurar cualquier conversación de coaching."},{"id":"c065","modulo":"coaching","nombre":"Modelo de Compromiso Laboral (Engagement)","autor":"William Kahn","anio":1990,"resumen":"Define el compromiso como la medida en que una persona se implica física, cognitiva y emocionalmente en su rol.","cuando_usar":"Diagnosticar por qué alguien del equipo parece desconectado sin decir por qué."},{"id":"c066","modulo":"coaching","nombre":"Modelo de las Tres Zonas","autor":"Karl Rohnke","anio":1974,"resumen":"Distingue zona de confort, de aprendizaje y de pánico, para calibrar cuánto reto es productivo sin generar bloqueo.","cuando_usar":"Decidir cuánto sacar a alguien de su zona de confort sin sobrepasarle."},{"id":"c067","modulo":"coaching","nombre":"Teoría de la Equidad","autor":"John Stacey Adams","anio":1963,"resumen":"Plantea que la motivación depende de comparar la propia relación esfuerzo-recompensa con la de otras personas del entorno.","cuando_usar":"Desmotivación por percepción de trato desigual respecto a un compañero."},{"id":"c068","modulo":"coaching","nombre":"Liderazgo Adaptativo","autor":"Ronald Heifetz, Marty Linsky","anio":1994,"resumen":"Distingue problemas técnicos (con solución conocida) de problemas adaptativos (que exigen cambiar creencias o hábitos del propio equipo).","cuando_usar":"Un reto de liderazgo que no se resuelve con más conocimiento técnico."},{"id":"c069","modulo":"coaching","nombre":"Las Cinco Prácticas del Liderazgo Ejemplar","autor":"James Kouzes, Barry Posner","anio":1987,"resumen":"Identifica cinco comportamientos de liderazgo efectivo: modelar el camino, inspirar visión, desafiar el proceso, habilitar a otros y alentar el corazón.","cuando_usar":"Marco general de desarrollo de liderazgo con comportamientos observables."},{"id":"c070","modulo":"coaching","nombre":"Compromiso Organizacional de Tres Componentes","autor":"John Meyer, Natalie Allen","anio":1991,"resumen":"Distingue el compromiso afectivo (querer quedarse), de continuidad (necesitar quedarse) y normativo (deber quedarse).","cuando_usar":"Entender por qué alguien se queda o se plantea irse de la empresa."},{"id":"c071","modulo":"coaching","nombre":"Los Primeros 90 Días","autor":"Michael Watkins","anio":2003,"resumen":"Marco para planificar la incorporación a un nuevo rol de liderazgo, priorizando el diagnóstico antes de implementar cambios.","cuando_usar":"Primer mes liderando un equipo remoto, heredado o nuevo."},{"id":"c072","modulo":"coaching","nombre":"Coaching Basado en Fortalezas","autor":"Alex Linley","anio":2008,"resumen":"Aplica la psicología positiva al desarrollo profesional, priorizando desarrollar fortalezas sobre corregir debilidades.","cuando_usar":"Diseño de un plan de desarrollo centrado en lo que la persona ya hace bien."},{"id":"c073","modulo":"coaching","nombre":"Entrenamiento en Comunicación Asertiva","autor":"Joseph Wolpe","anio":1958,"resumen":"Entrena a expresar necesidades y opiniones de forma directa y respetuosa, sin pasividad ni agresividad.","cuando_usar":"Negociar sin ceder de más ni imponerse en exceso."},{"id":"c074","modulo":"coaching","nombre":"Método 'Come la Rana'","autor":"Brian Tracy (popularizando una idea atribuida a Mark Twain)","anio":2001,"resumen":"Recomienda abordar primero la tarea más difícil o postergada del día, cuando la energía y voluntad son mayores.","cuando_usar":"Procrastinación de una tarea concreta que genera malestar por evitarla."},{"id":"c075","modulo":"coaching","nombre":"Feedback Ascendente","autor":"Prácticas de gestión participativa","anio":1980,"resumen":"Estructura para que el equipo dé feedback a su manager, no solo al revés, como parte de una cultura de mejora continua.","cuando_usar":"Construir una cultura de feedback continuo y no solo puntual."},{"id":"c076","modulo":"coaching","nombre":"La Escalera de la Responsabilidad","autor":"John G. Miller","anio":2004,"resumen":"Modelo QBQ (la pregunta detrás de la pregunta) que entrena a formular preguntas que fomentan la responsabilidad personal en vez de la culpa externa.","cuando_usar":"Un equipo que tiende a buscar culpables en vez de soluciones."},{"id":"c077","modulo":"coaching","nombre":"Liderazgo de Nivel 5","autor":"Jim Collins","anio":2001,"resumen":"Describe un liderazgo que combina humildad personal con una voluntad profesional férrea, asociado a resultados sostenibles.","cuando_usar":"Reflexionar sobre el propio estilo de liderazgo a largo plazo."},{"id":"c078","modulo":"coaching","nombre":"Autonomía, Maestría y Propósito (Drive)","autor":"Daniel Pink","anio":2009,"resumen":"Plantea que la motivación intrínseca real depende de sentir autonomía, poder mejorar en algo (maestría) y tener un propósito.","cuando_usar":"Motivar a alguien que ha perdido las ganas, más allá de incentivos económicos."},{"id":"c079","modulo":"coaching","nombre":"Conversaciones de Reconocimiento","autor":"Prácticas de gestión del talento","anio":2015,"resumen":"Estructura conversaciones breves y frecuentes de reconocimiento específico, más efectivas que el reconocimiento genérico o esporádico.","cuando_usar":"El reconocimiento actual no parece tener impacto real en la motivación."},{"id":"c080","modulo":"coaching","nombre":"Teoría de las Expectativas","autor":"Victor Vroom","anio":1964,"resumen":"La motivación depende de tres factores: expectativa (puedo lograrlo), instrumentalidad (llevará a un resultado) y valencia (me importa ese resultado).","cuando_usar":"Diagnosticar en qué punto concreto se rompe la motivación de alguien hacia una tarea."},{"id":"c081","modulo":"coaching","nombre":"Modelo Integrado de Desarrollo Grupal (IMGD)","autor":"Susan Wheelan","anio":1990,"resumen":"Describe cuatro etapas de madurez de un equipo (dependencia, conflicto, confianza, trabajo) con intervenciones distintas en cada una.","cuando_usar":"Diagnosticar en qué fase de madurez está un equipo concreto."},{"id":"c082","modulo":"coaching","nombre":"Liderazgo Distribuido","autor":"James Spillane","anio":2001,"resumen":"Plantea el liderazgo como una práctica compartida entre varias personas del equipo, no como una función exclusiva del manager.","cuando_usar":"Equipos donde el manager quiere repartir responsabilidad de liderazgo."},{"id":"c083","modulo":"coaching","nombre":"Coaching de Equipos (Team Coaching)","autor":"Peter Hawkins","anio":2011,"resumen":"Aplica el modelo GROW y la mirada sistémica al equipo como conjunto, no solo a la conversación individual.","cuando_usar":"El reto no es de una persona concreta, sino del equipo como sistema."},{"id":"c084","modulo":"coaching","nombre":"Capital Psicológico (PsyCap)","autor":"Fred Luthans","anio":2007,"resumen":"Define cuatro recursos entrenables (esperanza, autoeficacia, resiliencia, optimismo) que predicen el desempeño laboral.","cuando_usar":"Diseño de un plan de desarrollo centrado en recursos psicológicos, no solo técnicos."},{"id":"c085","modulo":"coaching","nombre":"Preguntas Circulares","autor":"Mara Selvini Palazzoli (terapia sistémica)","anio":1980,"resumen":"Preguntas que invitan a describir cómo ve una situación un tercero, para ganar perspectiva sobre una dinámica relacional.","cuando_usar":"Conflictos de equipo donde cuesta ver la perspectiva de la otra persona."},{"id":"c086","modulo":"coaching","nombre":"Coaching de Transición de Carrera","autor":"Nancy Schlossberg","anio":1981,"resumen":"Modelo de las 4S (Situación, Yo/Self, Apoyos, Estrategias) para afrontar cualquier transición profesional significativa.","cuando_usar":"Cambio de rol, promoción o etapa profesional importante."},{"id":"c087","modulo":"coaching","nombre":"Feedback 4A","autor":"Cultura corporativa de Netflix","anio":2010,"resumen":"Marco de feedback: con Intención de Ayudar, Accionable, Apreciado y Aceptar o Rechazar sin resentimiento.","cuando_usar":"Establecer normas claras de cómo dar y recibir feedback en un equipo."},{"id":"c088","modulo":"coaching","nombre":"Compromiso Discrecional","autor":"Estudios de employee engagement, Towers Watson","anio":2005,"resumen":"Mide el esfuerzo extra que una persona da voluntariamente más allá de lo estrictamente exigido por su puesto.","cuando_usar":"Diferenciar cumplimiento mínimo de compromiso real con el equipo."},{"id":"c089","modulo":"coaching","nombre":"Conversaciones de Desarrollo","autor":"Julie Winkle Giulioni, Beverly Kaye","anio":2012,"resumen":"Plantea integrar conversaciones breves de desarrollo profesional en el día a día, no reservarlas solo a la evaluación anual.","cuando_usar":"Un equipo pide más desarrollo de carrera y no hay espacio formal para ello."},{"id":"c090","modulo":"coaching","nombre":"Liderazgo Inclusivo","autor":"Juliet Bourke, Andrea Espedido","anio":2019,"resumen":"Identifica seis rasgos de liderazgo (compromiso, humildad, curiosidad cultural...) asociados a equipos que se sienten incluidos.","cuando_usar":"Un equipo diverso donde algunas voces participan menos que otras."},{"id":"c091","modulo":"coaching","nombre":"Toma de Decisiones por Consentimiento","autor":"Gerard Endenburg (sociocracia)","anio":1970,"resumen":"Una decisión avanza si nadie tiene una objeción razonada y argumentada, sin necesitar consenso total.","cuando_usar":"Decisiones de equipo que se bloquean buscando unanimidad total."},{"id":"c092","modulo":"coaching","nombre":"Retrospectivas Ágiles entre Pares","autor":"Prácticas ágiles de gestión de equipos","anio":2001,"resumen":"Estructura reuniones periódicas de equipo para revisar qué funcionó, qué no, y qué se prueba de forma diferente.","cuando_usar":"Un equipo que repite los mismos errores de proceso sin revisarlos nunca."},{"id":"c093","modulo":"coaching","nombre":"Coaching de Habilidades de Presentación","autor":"Nancy Duarte","anio":2010,"resumen":"Estructura narrativa (situación actual vs. futuro deseado) para preparar presentaciones que generan impacto y no solo información.","cuando_usar":"Preparar una presentación importante ante dirección o cliente."},{"id":"c094","modulo":"coaching","nombre":"Gestión de Expectativas","autor":"Buenas prácticas de gestión de proyectos (PMI)","anio":1990,"resumen":"Marco para alinear explícitamente qué espera cada parte de un proyecto o encargo antes de que surja el desacuerdo.","cuando_usar":"Malentendidos recurrentes sobre qué se esperaba de una entrega o tarea."},{"id":"c095","modulo":"coaching","nombre":"Liderazgo Compartido","autor":"Craig Pearce, Jay Conger","anio":2003,"resumen":"Plantea que el liderazgo puede ejercerse de forma horizontal entre varios miembros del equipo según el momento y la tarea.","cuando_usar":"Equipos muy dependientes de una única figura de liderazgo."},{"id":"c096","modulo":"coaching","nombre":"Curva del Cambio Aplicada a Equipos","autor":"Adaptación organizacional del modelo de Kübler-Ross","anio":2000,"resumen":"Aplica las fases emocionales del duelo (negación, resistencia, exploración, compromiso) a la reacción de un equipo ante un cambio.","cuando_usar":"Anticipar y acompañar la reacción de un equipo ante un anuncio de cambio."},{"id":"c097","modulo":"coaching","nombre":"Liderazgo en Entornos VUCA","autor":"US Army War College","anio":1987,"resumen":"Marco para liderar en contextos Volátiles, Inciertos, Complejos y Ambiguos, priorizando claridad de propósito sobre control total.","cuando_usar":"Liderar en medio de incertidumbre alta sin toda la información disponible."},{"id":"c098","modulo":"coaching","nombre":"Coaching Axiológico (Basado en Valores)","autor":"Salvador García, Shimon Dolan","anio":1997,"resumen":"Explora los valores personales y organizacionales en conflicto detrás de una decisión difícil, para tomarla con más coherencia.","cuando_usar":"Decisiones profesionales donde chocan valores personales y exigencias del puesto."},{"id":"c099","modulo":"coaching","nombre":"Modelo de Herencia de Equipo","autor":"Prácticas de gestión de transiciones de liderazgo","anio":2005,"resumen":"Marco para diagnosticar la reputación, dinámicas y heridas de un equipo heredado antes de intentar cambiarlo.","cuando_usar":"Heredar un equipo con mala fama o con conflictos previos al propio manager."},{"id":"c100","modulo":"coaching","nombre":"Estilo de Liderazgo Contingente","autor":"Fred Fiedler","anio":1964,"resumen":"Plantea que no existe un único estilo de liderazgo eficaz: la eficacia depende de la relación entre estilo del líder y el contexto concreto.","cuando_usar":"Explicar por qué el mismo estilo de liderazgo no funciona igual con todas las personas."}];

const ANTHROPIC_API_URL = 'https://api.anthropic.com/v1/messages';
const MODEL = 'claude-sonnet-5'; // revisa docs.claude.com/en/docs/about-claude/models para el string vigente
const MAX_TOKENS = 1024;
const MAX_METODOLOGIAS_EN_CONTEXTO = 8;

// -- Seleccion simple por palabras clave (sin embeddings, sin base de datos externa) --
function seleccionarMetodologiasRelevantes(textoUsuario, modulo) {
  if (!textoUsuario) return [];
  const texto = textoUsuario.toLowerCase();
  const palabras = texto.match(/[a-zà-öø-ÿñ]{4,}/gi) || [];

  const candidatas = METODOLOGIAS.filter((m) => {
    if (modulo === 'bienestar') return m.modulo === 'bienestar';
    if (modulo === 'coaching') return m.modulo === 'coaching';
    return true; // modulo "ambos" -> se buscan en las 200
  });

  const puntuadas = candidatas.map((m) => {
    const campoPrincipal = (m.nombre + ' ' + m.cuando_usar).toLowerCase();
    const campoSecundario = m.resumen.toLowerCase();
    let score = 0;
    for (const palabra of palabras) {
      if (campoPrincipal.includes(palabra)) score += 2;
      else if (campoSecundario.includes(palabra)) score += 1;
    }
    return { ...m, score };
  });

  return puntuadas
    .filter((m) => m.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, MAX_METODOLOGIAS_EN_CONTEXTO);
}

function formatearContexto(lista) {
  if (!lista.length) return '';
  const bloques = lista
    .map(
      (m) =>
        `- ${m.nombre} (${m.autor}, ${m.anio}) -- ${m.resumen} Usala cuando: ${m.cuando_usar}`
    )
    .join('\n');
  return `\n\nCONTEXTO ADICIONAL -- METODOLOGIAS ENCONTRADAS EN LA BASE DE DATOS RELEVANTES PARA ESTE MENSAJE\nSi alguna de estas encaja mejor que las que ya tienes en tu lista de metodologias, puedes usarla y citarla por su nombre y autor. Si ninguna encaja bien, ignoralas y usa tu propio criterio.\n${bloques}`;
}

function extraerUltimoMensajeTexto(messages) {
  if (!Array.isArray(messages) || !messages.length) return '';
  const ultimo = messages[messages.length - 1];
  if (!ultimo || ultimo.role !== 'user') return '';
  if (typeof ultimo.content === 'string') return ultimo.content;
  if (Array.isArray(ultimo.content)) {
    const bloqueTexto = ultimo.content.find((b) => b.type === 'text');
    return bloqueTexto ? bloqueTexto.text : '';
  }
  return '';
}

export default async (req) => {
  if (req.method !== 'POST') {
    return new Response('Method not allowed', { status: 405 });
  }

  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    return new Response(
      JSON.stringify({ error: 'Falta configurar ANTHROPIC_API_KEY en las variables de entorno de Netlify.' }),
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }

  let body;
  try {
    body = await req.json();
  } catch {
    return new Response(JSON.stringify({ error: 'JSON invalido' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  const { messages, system, modulo } = body;

  if (!Array.isArray(messages) || messages.length === 0) {
    return new Response(JSON.stringify({ error: 'Falta el array "messages"' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  const ultimoMensaje = extraerUltimoMensajeTexto(messages);
  const relevantes = seleccionarMetodologiasRelevantes(ultimoMensaje, modulo);
  const systemFinal = (system || '') + formatearContexto(relevantes);

  const anthropicRes = await fetch(ANTHROPIC_API_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01',
    },
    body: JSON.stringify({
      model: MODEL,
      max_tokens: MAX_TOKENS,
      system: systemFinal,
      messages,
      stream: true,
    }),
  });

  if (!anthropicRes.ok || !anthropicRes.body) {
    const errText = await anthropicRes.text().catch(() => '');
    return new Response(JSON.stringify({ error: 'Error llamando a Anthropic', detail: errText }), {
      status: 502,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  return new Response(anthropicRes.body, {
    status: 200,
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
    },
  });
};

export const config = {
  path: '/.netlify/functions/chat',
};
